catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        hideInitialFields();
        return;
    }

    var tableName = g_form.getValue('table');

    if (tableName) {
        if (newValue == 'add' && tableName.indexOf('custody_reason_code') > -1) {
            reasonCodeAddFields();
            reasonCodeAddFieldsHide();
        } else if (newValue == 'modify' && tableName.indexOf('custody_reason_code') > -1) {
            reasonCodeModifyFields();
            reasonCodeModifyFieldsHide();
        } else if (newValue == 'delete' && tableName.indexOf('custody_reason_code') > -1) {
            reasonCodeDeleteFields();
            reasonCodeDeleteFieldsHide();
        } else if (newValue == 'add' && tableName.indexOf('custody_location_code') > -1) {
            locationCodeAddFields();
            locationCodeAddFieldsHide();
        } else if (newValue == 'modify' && tableName.indexOf('custody_location_code') > -1) {
            locationCodeModifyFields();
            locationCodeModifyFieldsHide();
        } else if (newValue == 'delete' && tableName.indexOf('custody_location_code') > -1) {
            locationCodeDeleteFields();
            locationCodeDeleteFieldsHide();
        } else if (newValue == 'add' && tableName.indexOf('u_market_limit') > -1) {
            bandAddFields();
            bandAddFieldsHide();
        } else if (newValue == 'modify' && tableName.indexOf('u_market_limit') > -1) {
            bandModifyFields();
            bandModifyFieldsHide();
        } else if (newValue == 'delete' && tableName.indexOf('u_market_limit') > -1) {
            bandDeleteFields();
            bandDeleteFieldsHide();
        } else {
            hideInitialFields();
        }
    } else {
        hideInitialFields();
    }


    /*---------------------------------FUNCTIONS----------------------------------------*/

    function hideInitialFields() {
        var fieldsToHideInitial = getFieldsToHideInitial();
        fieldsToHideInitial.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function getFieldsToHideInitial() {
        return [
			'owning_business',

            'old_reason_code', 'reason_code', 'new_reason_code',
            'old_reason_code_label', 'reason_code_label', 'new_reason_code_label',
            'old_reason_code_type', 'reason_code_type',
            'old_reason_description', 'reason_description',
            'old_reason_dashboard_group', 'reason_dashboard_group',

            'old_location_code', 'location_code', 'new_location_code',
            'old_location_description', 'location_description', 'new_location_description',
            'old_region', 'region', 'new_region',

            'old_local_limit', 'local_limit', 'new_local_limit',
            'old_currency', 'currency', 'new_currency',
            'old_band_group', 'band_group', 'new_band_group'
        ];
    }

    //***************************REASON CODE TABLE************************************
    //----------------Add Action----------------
    function reasonCodeAddFields() {
        var fieldsToShow = reasonCodeFields('reasonCodeAddFields');
        fieldsToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function reasonCodeAddFieldsHide() {
        var fieldsToHide = reasonCodeFields('reasonCodeAddFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    //--------------Modify Action--------------
    function reasonCodeModifyFields() {
        var fieldsToShow1 = reasonCodeFields('reasonCodeModifyFields1');
        fieldsToShow1.forEach(function(field1) {
            g_form.setDisplay(field1, true);
            g_form.setMandatory(field1, true);
        });
        var fieldsToShow2 = reasonCodeFields('reasonCodeModifyFields2');
        fieldsToShow2.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
		// g_form.setLabelOf('reason_code', 'New Reason Code');
		// g_form.setLabelOf('reason_code_label', 'New Reason Code Label');
    }

    function reasonCodeModifyFieldsHide() {
        var fieldsToHide = reasonCodeFields('reasonCodeModifyFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    //--------------Delete Action-----------------
    function reasonCodeDeleteFields() {
        var fieldsToShow = reasonCodeFields('reasonCodeDeleteFields');
        fieldsToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function reasonCodeDeleteFieldsHide() {
        var fieldsToHide = reasonCodeFields('reasonCodeDeleteFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    //----------Reason Code Table Fields-------------------
    function reasonCodeFields(funcName) {
        if (funcName === 'reasonCodeAddFields') {
            return [
                'owning_business','reason_code', 'reason_code_label', 'reason_code_type', 'reason_description', 'reason_dashboard_group'
            ];

        } else if (funcName === 'reasonCodeAddFieldsHide') {
            return [
                'old_reason_code', 'old_reason_code_label', 'old_reason_code_type', 'old_reason_description', 'old_reason_dashboard_group', 'new_reason_code', 'new_reason_code_label',
				'old_location_code', 'location_code', 'old_location_description', 'location_description', 'old_region', 'region',  'new_location_code', 'new_location_description', 'new_region',
				'old_local_limit', 'local_limit', 'old_currency', 'currency', 'old_band_group', 'band_group', 'new_local_limit', 'new_currency', 'new_band_group'
            ];

        } else if (funcName === 'reasonCodeModifyFields1') {
            return [
                'owning_business','old_reason_code', 'old_reason_code_label'
            ];

        } else if (funcName === 'reasonCodeModifyFields2') {
            return [
                'new_reason_code', 'new_reason_code_label'
            ];

        } else if (funcName === 'reasonCodeModifyFieldsHide') {
            return [
                'reason_code', 'reason_code_label', 'reason_code_type', 'reason_description', 'reason_dashboard_group', 'old_reason_code_type', 'old_reason_description', 'old_reason_dashboard_group', 'old_location_code', 'location_code', 'old_location_description', 'location_description', 'old_region', 'region', 'old_local_limit', 'local_limit', 'old_currency', 'currency', 'old_band_group', 'band_group', 'new_location_code', 'new_location_description', 'new_region','new_local_limit', 'new_currency', 'new_band_group'
            ];

        } else if (funcName === 'reasonCodeDeleteFields') {
            return [
                'owning_business', 'reason_code', 'reason_code_label'
            ];

        } else if (funcName === 'reasonCodeDeleteFieldsHide') {
            return [
                'new_reason_code', 'new_reason_code_label','reason_code_type', 'reason_description', 'reason_dashboard_group', 'old_reason_code', 'old_reason_code_label', 'old_reason_code_type', 'old_reason_description', 'old_reason_dashboard_group', 'old_location_code', 'location_code', 'old_location_description', 'location_description', 'old_region', 'region', 'old_local_limit', 'local_limit', 'old_currency', 'currency', 'old_band_group', 'band_group', 'new_location_code', 'new_location_description', 'new_region','new_local_limit', 'new_currency', 'new_band_group'
            ];
        }
    }
    //*****************************************************************************


    //***************************LOCATION CODE TABLE*******************************
    function locationCodeAddFields() {
        var fieldsToShow = locationCodeFields('locationCodeAddFields');
        fieldsToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function locationCodeAddFieldsHide() {
        var fieldsToHide = locationCodeFields('locationonCodeAddFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function locationCodeModifyFields() {
        var fieldsToShow1 = locationCodeFields('locationCodeModifyFields1');
        fieldsToShow1.forEach(function(field1) {
            g_form.setDisplay(field1, true);
            g_form.setMandatory(field1, true);
        });
        var fieldsToShow2 = locationCodeFields('locationCodeModifyFields2');
        fieldsToShow2.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function locationCodeModifyFieldsHide() {
        var fieldsToHide = locationCodeFields('locationonCodeModifyFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function locationCodeDeleteFields() {
        var fieldsToShow = locationCodeFields('locationCodeDeleteFields');
        fieldsToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function locationCodeDeleteFieldsHide() {
        var fieldsToHide = locationCodeFields('locationCodeDeleteFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function locationCodeFields(funcName) {
        if (funcName === 'locationCodeAddFields') {
            return [
                'owning_business', 'location_code', 'location_description', 'region'
            ];

        } else if (funcName === 'locationCodeAddFieldsHide') {
            return [
                'old_reason_code', 'reason_code',
                'old_reason_code_label', 'reason_code_label',
                'old_reason_code_type', 'reason_code_type',
                'old_reason_description', 'reason_description',
                'old_reason_dashboard_group', 'reason_dashboard_group',
                'old_location_code', 'old_location_description', 'old_region',
                'old_local_limit', 'local_limit',
                'old_currency', 'currency',
                'old_band_group', 'band_group',
				'new_reason_code', 'new_reason_code_label', 'new_location_code', 'new_location_description', 'new_region','new_local_limit', 'new_currency', 'new_band_group'
            ];

        } else if (funcName === 'locationCodeModifyFields1') {
            return [
                'owning_business', 'old_location_code', 'old_location_description', 'old_region'
            ];

        } else if (funcName === 'locationCodeModifyFields2') {
            return [
                'new_location_code', 'new_location_description', 'new_region'
            ];

        } else if (funcName === 'locationCodeModifyFieldsHide') {
            return [
                'old_reason_code', 'reason_code',
                'old_reason_code_label', 'reason_code_label',
                'old_reason_code_type', 'reason_code_type',
                'old_reason_description', 'reason_description',
                'old_reason_dashboard_group', 'reason_dashboard_group',
                'old_local_limit', 'local_limit',
                'old_currency', 'currency',
                'old_band_group', 'band_group',
				'new_reason_code', 'new_reason_code_label','new_local_limit', 'new_currency', 'new_band_group', 'location_code', 'location_description', 'region'
            ];

        } else if (funcName === 'locationCodeDeleteFields') {
            return [
                'owning_business', 'location_code', 'location_description'
            ];

        } else if (funcName === 'locationCodeDeleteFieldsHide') {
            return [
                'old_reason_code', 'reason_code',
                'old_reason_code_label', 'reason_code_label',
                'old_reason_code_type', 'reason_code_type',
                'old_reason_description', 'reason_description',
                'old_reason_dashboard_group', 'reason_dashboard_group',
                'old_location_code',
                'old_location_description',
                'old_region', 'region',
                'old_local_limit', 'local_limit',
                'old_currency', 'currency',
                'old_band_group', 'band_group',
				'new_reason_code', 'new_reason_code_label', 'new_location_code', 'new_location_description', 'new_region','new_local_limit', 'new_currency', 'new_band_group'
            ];
        }
    }

    //*****************************************************************************

    //*******************BAND LIMIT(sys_user_group) TABLE**************************
    function bandAddFields() {
        var fieldsToShow = bandFields('bandAddFields');
        fieldsToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function bandAddFieldsHide() {
        var fieldsToHide = bandFields('bandAddFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function bandModifyFields() {
        var fieldsToShow1 = bandFields('bandModifyFields1');
        fieldsToShow1.forEach(function(field1) {
            g_form.setDisplay(field1, true);
            g_form.setMandatory(field1, true);
        });
        var fieldsToShow2 = bandFields('bandModifyFields2');
        fieldsToShow2.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function bandModifyFieldsHide() {
        var fieldsToHide = bandFields('bandModifyFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function bandDeleteFields() {
        var fieldsToShow = bandFields('bandDeleteFields');
        fieldsToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
            g_form.setMandatory(field, true);
        });
    }

    function bandDeleteFieldsHide() {
        var fieldsToHide = bandFields('bandDeleteFieldsHide');
        fieldsToHide.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function bandFields(funcName) {
        if (funcName === 'bandAddFields') {
            return [
                'owning_business', 'local_limit', 'currency', 'band_group'
            ];

        } else if (funcName === 'bandAddFieldsHide') {
            return [
                'old_reason_code', 'reason_code',
                'old_reason_code_label', 'reason_code_label',
                'old_reason_code_type', 'reason_code_type',
                'old_reason_description', 'reason_description',
                'old_reason_dashboard_group', 'reason_dashboard_group',
                'old_location_code', 'location_code',
                'old_location_description', 'location_description',
                'old_region', 'region',
                'old_band_group', 'old_local_limit', 'old_currency',
				'new_reason_code', 'new_reason_code_label', 'new_location_code', 'new_location_description', 'new_region','new_local_limit', 'new_currency', 'new_band_group'
            ];

        } else if (funcName === 'bandModifyFields1') {
            return [
                'owning_business', 'old_local_limit', 'old_currency', 'old_band_group'
            ];

        } else if (funcName === 'bandModifyFields2') {
            return [
                'new_local_limit', 'new_currency', 'new_band_group'
            ];

        } else if (funcName === 'bandModifyFieldsHide') {
            return [
                'old_reason_code', 'reason_code',
                'old_reason_code_label', 'reason_code_label',
                'old_reason_code_type', 'reason_code_type',
                'old_reason_description', 'reason_description',
                'old_reason_dashboard_group', 'reason_dashboard_group',
                'old_location_code', 'location_code',
                'old_location_description', 'location_description',
                'old_region', 'region',
				'new_reason_code', 'new_reason_code_label', 'new_location_code', 'new_location_description', 'new_region', 'local_limit', 'currency', 'band_group'
            ];

        } else if (funcName === 'bandDeleteFields') {
            return [
                'owning_business', 'local_limit', 'currency', 'band_group'
            ];

        } else if (funcName === 'bandDeleteFieldsHide') {
            return [
                'old_reason_code', 'reason_code',
                'old_reason_code_label', 'reason_code_label',
                'old_reason_code_type', 'reason_code_type',
                'old_reason_description', 'reason_description',
                'old_reason_dashboard_group', 'reason_dashboard_group',
                'old_location_code', 'location_code',
                'old_location_description', 'location_description',
                'old_region', 'region',
                'old_band_group', 'old_local_limit', 'old_currency',
				'new_reason_code', 'new_reason_code_label', 'new_location_code', 'new_location_description', 'new_region','new_local_limit', 'new_currency', 'new_band_group'
            ];
        }
    }
}
